<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Double Pendulum — RK4</title>
<style>
  html, body { margin: 0; height: 100%; background: #0b0e14; overflow: hidden; }
  canvas { display: block; }
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
"use strict";

// ===== Physics: exact Lagrangian equations of motion =====
// State y = [th1, w1, th2, w2]
// m1 L1^2 th1'' + m2 L1^2 th1'' + m2 L1 L2 cos(th1-th2) th2''
//   + m2 L1 L2 sin(th1-th2) w2^2 ... etc. Standard closed form:
//
// (m1+m2) L1 a1 + m2 L2 a2 cos(d) + m2 L2 w2^2 sin(d) + (m1+m2) g sin(th1) = 0
// L2 a2 + L1 a1 cos(d) - L1 w1^2 sin(d) + g sin(th2) = 0
// where d = th1 - th2. Solved for a1, a2 (angular accelerations).

const m1 = 1.5, m2 = 1.0;
const L1 = 1.0, L2 = 1.0;   // meters (scaled for drawing)
const g  = 9.81;

function deriv(y) {
  const [t1, w1, t2, w2] = y;
  const d = t1 - t2;
  const cd = Math.cos(d), sd = Math.sin(d);

  const a = (m1 + m2);
  const b = m2 * cd;
  const c = m2 * (L2 / L1);
  const p = -m2 * L2 / L1 * w2 * w2 * sd - (m1 + m2) * g / L1 * Math.sin(t1);
  const q =  L1 / L2 * w1 * w1 * sd - g / L2 * Math.sin(t2);

  // Solve 2x2 system:
  // a*a1 + b*a2 = p
  // c*a1 + 1*a2 = q   (after dividing eq2 by L2^2 m2 appropriately)
  const det = a * 1 - b * c;
  const a1 = (p * 1 - b * q) / det;
  const a2 = (a * q - c * p) / det;

  return [w1, a1, w2, a2];
}

// ===== RK4 integrator =====
function rk4(y, h) {
  const k1 = deriv(y);
  const y2 = y.map((v, i) => v + h / 2 * k1[i]);
  const k2 = deriv(y2);
  const y3 = y.map((v, i) => v + h / 2 * k2[i]);
  const k3 = deriv(y3);
  const y4 = y.map((v, i) => v + h * k3[i]);
  const k4 = deriv(y4);
  return y.map((v, i) => v + h / 6 * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]));
}

// ===== Setup =====
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");

let W, H, cx, cy, scale;
function resize() {
  W = canvas.width = innerWidth;
  H = canvas.height = innerHeight;
  cx = W / 2; cy = H * 0.35;
  scale = Math.min(W, H) * 0.22; // pixels per meter
}
addEventListener("resize", resize);
resize();

// Initial conditions (chaotic regime)
let y = [Math.PI * 0.72, 0, Math.PI * 0.55, 0];

// Motion trail of the second bob
const TRAIL_MAX = 4000;
const trail = [];

// Fixed physics timestep with accumulator
const dt = 1 / 600;
let acc = 0;
let last = performance.now();

function draw() {
  // Fade previous frame slightly (trail effect for rods)
  ctx.fillStyle = "rgba(11,14,20,0.25)";
  ctx.fillRect(0, 0, W, H);

  const [t1, , t2] = y;
  const x1 = cx + L1 * scale * Math.sin(t1);
  const y1 = cy + L1 * scale * Math.cos(t1);
  const x2 = x1 + L2 * scale * Math.sin(t2);
  const y2 = y1 + L2 * scale * Math.cos(t2);

  // Motion trail
  trail.push(x2, y2);
  if (trail.length > TRAIL_MAX * 2) trail.splice(0, 2);

  ctx.lineWidth = 1.5;
  ctx.strokeStyle = "rgba(80,200,255,0.7)";
  ctx.beginPath();
  for (let i = 0; i < trail.length; i += 2) {
    if (i === 0) ctx.moveTo(trail[i], trail[i + 1]);
    else ctx.lineTo(trail[i], trail[i + 1]);
  }
  ctx.stroke();

  // Pivot
  ctx.fillStyle = "#8892a6";
  ctx.beginPath();
  ctx.arc(cx, cy, 5, 0, Math.PI * 2);
  ctx.fill();

  // Rods
  ctx.strokeStyle = "#dfe6f0";
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(cx, cy); ctx.lineTo(x1, y1); ctx.lineTo(x2, y2);
  ctx.stroke();

  // Bobs (radius ~ mass^(1/3))
  const r1 = 8 * Math.cbrt(m1), r2 = 8 * Math.cbrt(m2);
  ctx.fillStyle = "#ffb347";
  ctx.beginPath(); ctx.arc(x1, y1, r1, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "#ff5e78";
  ctx.beginPath(); ctx.arc(x2, y2, r2, 0, Math.PI * 2); ctx.fill();

  // Info
  ctx.fillStyle = "rgba(220,230,245,0.75)";
  ctx.font = "13px monospace";
  ctx.fillText("Double pendulum — RK4, dt = 1/600 s. Click to reset.", 12, 20);
}

function frame(now) {
  let elapsed = (now - last) / 1000;
  last = now;
  if (elapsed > 0.1) elapsed = 0.1; // avoid spiral of death
  acc += elapsed;
  while (acc >= dt) {
    y = rk4(y, dt);
    acc -= dt;
  }
  draw();
  requestAnimationFrame(frame);
}

canvas.addEventListener("click", () => {
  // Reset with a small random kick
  y = [Math.PI * (0.6 + Math.random() * 0.3), 0,
       Math.PI * (0.4 + Math.random() * 0.4), 0];
  trail.length = 0;
});

requestAnimationFrame(frame);
</script>
</body>
</html>
```

The equations of motion are the exact Lagrangian result for a double pendulum (two coupled second-order ODEs solved as a 2×2 linear system for the angular accelerations each step), integrated with classic RK4 at a fixed 600 Hz timestep via an accumulator loop, decoupled from the render rate. The trail records the second bob's position and is drawn each frame; click anywhere to reset with new initial angles.
